  if not (krt.is_list(xs) or krt.is_froz(xs)) then
    krt.fail("TYPE_ERROR", "expected list, found " .. krt.typeof(xs))
  end
  local n = #xs
  if n == 0 then krt.fail("VALUE_ERROR", "empty choice") end
  return xs[math.floor(math.random() * n) + 1]
end

local function extrema(args, count, want_max)
  local m
  if count == 1 and krt.is_list(args[1]) then
    local xs = args[1]
    if #xs == 0 then krt.fail("VALUE_ERROR", "min/max of empty list") end
    m = krt.as_flint(xs[1])
    for i = 2, #xs do
      local v = krt.as_flint(xs[i])
      if want_max then
        if v > m then m = v end
      else
        if v < m then m = v end
      end
    end
    return m
  end
  if count == 0 then krt.fail("VALUE_ERROR", "min/max needs a value") end
  m = krt.as_flint(args[1])
  for i = 2, count do
    local v = krt.as_flint(args[i])
    if want_max then
      if v > m then m = v end
    else
      if v < m then m = v end
    end
  end
  return m
end

