    return stmts", "                str cvt = cw[type]", "                if cvt != \"flint\" OR NOT is_numeric(cexpr[t]):", "                    fail(st, cop_tok, \"TYPE_ERROR\", cat([\"numeric operands of '\", cop_full, \"'\"]), cexpr[t])", "                    return stmts", "                bool cmaybe = FALSE", "                if cw[kind] == \"global\":", "                    dict cgnl = st[gnullable]", "                    dict cgmu = st[gmaybe]", "                    if cgnl.contains(cname):", "                        cmaybe = TRUE", "                    if cgmu.contains(cname):", "                        cmaybe = TRUE", "                    cgnl.remove(cname)", "                else:", "                    dict cnl = st[nullable]", "                    dict cmu = st[maybe_unset]", "                    if cnl.contains(cname):", "                        cmaybe = TRUE", "                    if cmu.contains(cname):", "                        cmaybe = TRUE", "                    cnl.remove(cname)", "                node = {k: \"compound\", name: cname, lua: cw[lua], op: cop, expr: cexpr, nullable: cmaybe, line: ctok[line], col: ctok[col]}", "            else:", "                dict e = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return stmts", "                if e[k] == \"self_init\":", "                    dict sctx = st[model_ctx]", "                    if sctx is NONE OR NOT sctx[in_construct]:", "                        fail(st, e, \"SCOPE_ERROR\", \"self(...) in construct\", \"self(...) outside construct\")", "                        return stmts", "                    if st[block_depth] != sctx[level] OR len(stmts) != 0:", "                        fail(st, e, \"SYNTAX_ERROR\", \"self(...) as the first statement of construct\", \"nested or later self(...)\")", "                        return stmts", "                    if sctx[self_seen]:", "                        fail(st, e, \"REDECLARE_ERROR\", \"one self(...)