, col: e[col]}", "                elif tok_is(tk(st), \"op\", \"=\"):", "                    str ek = e[k]", "                    if ek == \"field\":", "                        dict fb = e[base]", "                        dict fschema = model_schema(st, e[mname])", "                        str fld = e[name]", "                        dict mctx6 = st[model_ctx]", "                        bool in_con = FALSE", "                        if NOT (mctx6 is NONE) AND mctx6[in_construct] AND fb[k] == \"var\" AND fb[name] == \"self\":", "                            if st[block_depth] == mctx6[level]:", "                                in_con = TRUE", "                        if e[model_field]:", "                            fail(st, e, \"CONST_ERROR\", \"mutable field\", cat([\"model field '\", fld, \"' is read-only\"]))", "                            return stmts", "                        if e[is_const]:", "                            fail(st, e, \"CONST_ERROR\", \"mutable field\", cat([\"constant '\", fld, \"' is read-only\"]))", "                            return stmts", "                        dict ftypes6 = fschema[field_types]", "                        if NOT ftypes6.contains(fld):", "                            if NOT in_con OR NOT mctx6[self_done]:", "                                fail(st, e, \"NAME_ERROR\", cat([\"declared field of '\", e[mname], \"'\"]), cat([\"unknown '\", fld, \"'\"]))", "                                return stmts", "                            dict mctx6ps = mctx6[param_set]", "                            if mctx6ps.contains(fld):", "                                fail(st, e, \"REDECLARE_ERROR\", \"new field name\", cat([\"construct parameter '\", fld, \"'\"]))", "                                return stmts", "                            dict mcvar = st[vars]", "                            if mcvar.contains(fld):", "                                fail(st, e, \"REDECLARE_ERROR\", \"new field name\", cat([\"local '\", fld, \"'\"]))", "                                return stmts", "                        dict eq = advance(st)", "                        dict fexpr = parse_expr(st, 0)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        str fexpty = fexpr[t]", "                        if ftypes6.contains(fld):", "                            if NOT assignable(fexpty, ftypes6.take(fld)):", "                                fail(st, {line: fexpr[line], col: fexpr[col]}, \"TYPE_ERROR\", cat([\"field '\", fld, \"': type \", ftypes6.take(fld)]), fexpty)", "                                return stmts", "                            node = {k: \"field_assign\", base: fb, mname: e[mname], name: fld, expr: fexpr, type: ftypes6.take(fld), line: eq[line], col: eq[col]}", "                        else:", "                            if NOT is_scalar_type(fexpty):", "                                fail(st, {line: fexpr[line], col: fexpr[col]}, \"TYPE_ERROR\", \"scalar instance field (str, flint, bool)\", fexpty)", "                                return stmts", "                            add_model_field(st, fschema, e, fld, fexpty, TRUE)", "                            if NOT (st[err] is NONE):", "                                return stmts", "                            node = {k: \"field_create\", base: fb, mname: e[mname], name: fld, expr: fexpr, type: fexpty, line: eq[line], col: eq[col]}", "                    else:", "                        if ek != \"index\" AND ek != \"dget\":", "                            fail(st, {line: e[line], col: e[col]}, \"TYPE_ERROR\", \"variable, field or index as assignment target\", ek)", "                            return stmts", "                        if ek == \"index\":", "                            dict seb = e[base]", "                            if seb[t] == \"str\":", "                                fail(st, {line: e[line], col: e[col]}, \"TYPE_ERROR\", \"mutable index target\", \"str is immutable\")", "                                return stmts", "                        dict eq2 = advance(st)", "                        dict eval2 = parse_expr(st, 0)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        node = {k: \"setindex\", target: e, expr: eval2, line: eq2[line], col: eq2[col]}", "                else:", "                    node = {k: \"exprstmt\", expr: e, line: e[line], col: e[col]}", "            if NOT decl_block:", "                stmts.add(node)", "                if NOT block_stmt:", "                    dict nx2 = tk(st)", "                    if top:", "                        if nx2[type] == \"newline\":", "                            advance(st)", "                        elif nx2[type] != \"eof\":", "                            fail(st, nx2, \"SYNTAX_ERROR\", \"end of line\", describe_tok(nx2))", "                            return stmts", "                    else:", "                        if nx2[type] == \"newline\":", "                            advance(st)", "                        elif nx2[type] != \"dedent\":", "                            fail(st, nx2, \"SYNTAX_ERROR\", \"end of line\", describe_tok(nx2))", "                            return stmts", "    if NOT top:", "        if tk(st)[type] == \"dedent\":", "            advance(st)", "        st.add(\"block_depth\", st[block_depth] - 1)", "    return stmts", "", "# Загружает и разбирает один файл. Рекурсивен только сам в себя:", "# вложенные import разбираются этим же вызовом до основного parse_block.", "func process_source(dict st, str path, str src, bool fresh, bool capture_body) -> dict:", "    dict old = {toks: st[toks], pos: st[pos], path: st[path], source: st[source], err: st[err], vars: st[vars], nullable: st[nullable], maybe: st[maybe_unset], fors: st[for_names], gvars: st[gvars], gnullable: st[gnullable], gmaybe: st[gmaybe], funcs: st[funcs], names: st[names], fnames: st[fnames], exports: st[exports], models: st[models], vcounter: st[vcounter], fcounter: st[fcounter], block_depth: st[block_depth], loop_depth: st[loop_depth], cond_depth: st[cond_depth], in_func: st[in_func], func_ret: st[func_ret], func_returns: st[func_returns], model_ctx: st[model_ctx], try_id: st[try_id], try_depth: st[try_depth], try_loop_base: st[try_loop_base], ns_prefix: st[ns_prefix], ns_read_prefix: st[ns_read_prefix]}", "    if fresh:", "        st.add(\"ns_prefix\", \"\")", "        st.add(\"ns_read_prefix\", \"\")", "        st.add(\"vars\", {})", "        st.add(\"nullable\", {})", "        st.add(\"maybe_unset\", {})", "        st.add(\"for_names\", {})", "        st.add(\"gvars\", {})", "        st.add(\"gnullable\", {})", "        st.add(\"gmaybe\", {})", "        st.add(\"funcs\", {})", "        st.add(\"names\", {})", "        st.add(\"fnames\", {})", "        st.add(\"exports\", {})", "        st.add(\"models\", dict_copy(old[models]))", "        st.add(\"vcounter\", old[vcounter])", "        st.add(\"fcounter\", old[fcounter])", "        st.add(\"block_depth\", 0)", "        st.add(\"loop_depth\", 0)", "        st.add(\"cond_depth\", 0)", "        st.add(\"in_func\", FALSE)", "        st.add(\"func_ret\", \"NONE\")", "        st.add(\"func_returns\", [])", "        st.add(\"model_ctx\", NONE)", "        st.add(\"err\", NONE)", "    dict mlx = lex(src, path)", "    if NOT (mlx[err] is NONE):", "        dict e = mlx[err]", "        e.add(\"path\", path)", "        e.add(\"source\", src)", "        st.add(\"err\", e)", "        if fresh:", "            for rk1, rv1 in old:", "                st.add(rk1, rv1)", "            st.add(\"err\", e)", "        return {}", "    st.add(\"toks\", mlx[tokens])", "    st.add(\"pos\", 0)", "    st.add(\"path\", path)", "    st.add(\"source\", src)", "    if fresh:", "        add_prelude(st)", "    list stack = st[import_stack]", "    flint si = 0", "    while si < len(stack):", "        if stack[si] == path:", "            fail(st, tk(st), \"REDECLARE_ERROR\", \"import without a cycle\", path)", "            dict ce = st[err]", "            if fresh:", "                for rk2, rv2 in old:", "                    st.add(rk2, rv2)", "                st.add(\"err\", ce)", "            return {}", "        si += 1", "    stack.add(path)", "    st.add(\"import_stack\", stack)", "    flint i = 0", "    flint depth = 0", "    dict bodies = st[import_bodies]", "    while i < len(st[toks]) AND (st[err] is NONE):", "        dict it = st[toks][i]", "        flint nexti = i + 1", "        if it[type] == \"indent\":", "            depth += 1", "        elif it[type] == \"dedent\":", "            depth -= 1", "        elif depth == 0 AND it[type] == \"kw\" AND is_import_kw(it[value]):", "            st.add(\"pos\", i)", "            dict req = parse_import_syntax(st)", "            if NOT (st[err] is NONE):", "                break", "            str full = module_full_path(st, req[kind], req[path], req[tok])", "            dict cache = st[import_cache]", "            dict md = {}", "            bool cached = FALSE", "            if cache.contains(full):", "                md = cache.take(full)", "                cached = TRUE", "            else:", "                if NOT file_exists(full):", "                    fail(st, req[tok], \"FILE_ERROR\", \"module file\", full)", "                    break", "                str msrc = read_file(full)", "                md = process_source(st, full, msrc, TRUE, TRUE)", "                if NOT (st[err] is NONE):", "                    break", "                cache.add(full, md)", "                st.add(\"import_cache\", cache)", "            dict usemd = dict_copy(md)", "            usemd.add(\"bound\", {})", "            dict rtk = req[tok]", "            list reqnames = req[names]", "            str bind_prefix = \"\"", "            if req[kind] == \"import_lib\":", "                bind_prefix = cat([module_short_name(req[path]), \".\"])", "            if len(reqnames) == 0:", "                dict ex0 = usemd[exports]", "                for nm0, nvv0 in ex0:", "                    dict nt0 = {value: nm0, bind_as: cat([bind_prefix, nm0]), line: rtk[line], col: rtk[col]}", "                    bind_export(st, usemd, nt0)", "                    if NOT (st[err] is NONE):", "                        break", "            else:", "                for nt1 in reqnames:", "                    bind_export(st, usemd, nt1)", "                    if NOT (st[err] is NONE):", "                        break", "            if NOT (st[err] is NONE):", "                break", "            if NOT cached:", "                if usemd[vcounter] > st[vcounter]:", "                    st.add(\"vcounter\", usemd[vcounter])", "                if usemd[fcounter] > st[fcounter]:", "                    st.add(\"fcounter\", usemd[fcounter])", "            str bodykey = cat([path, \":\", str(req[start])])", "            if cached:", "                bodies.add(bodykey, [])", "            else:", "                bodies.add(bodykey, usemd[body])", "            st.add(\"import_bodies\", bodies)", "            nexti = st[pos]", "        i = nexti", "    list stack2 = st[import_stack]", "    stack2.del(len(stack2) - 1)", "    st.add(\"import_stack\", stack2)", "    if NOT capture_body:", "        st.add(\"pos\", 0)", "    dict result = {}", "    if capture_body AND (st[err] is NONE):", "        st.add(\"pos\", 0)", "        list body = parse_block(st, TRUE)", "        result = {path: path, body: body, exports: st[exports], vars: st[vars], nullable: st[nullable], funcs: st[funcs], names: st[names], fnames: st[fnames], gvars: st[gvars], gnullable: st[gnullable], gmaybe: st[gmaybe], vcounter: st[vcounter], fcounter: st[fcounter], bound: {}}", "    dict finalerr = st[err]", "    if fresh:", "        for rk3, rv3 in old:", "            st.add(rk3, rv3)", "        st.add(\"err\", finalerr)", "    return result", "", "# ---------- кодогенератор ----------", "", "func wrap_flint(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_flint(\", x, \")\"])", "    return x", "", "func wrap_str(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_str(\", x, \")\"])", "    return x", "", "func wrap_list(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_list(\", x, \")\"])", "    return x", "", "func wrap_dict(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_dict(\", x, \")\"])", "    return x", "", "func wrap_froz(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_froz(\", x, \")\"])", "    return x", "", "func wrap_bool(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_bool(\", x, \")\"])", "    return x", "", "# Приводит значение к базовому типу назначения; параметры типа проверяет рантайм.", "func as_base(str x, str target) -> str:", "    str b = base_type(target)", "    if b == \"flint\":", "        return cat([\"krt.as_flint(\", x, \")\"])", "    if b == \"str\":", "        return cat([\"krt.as_str(\", x, \")\"])", "    if b == \"bool\":", "        return cat([\"krt.as_bool(\", x, \")\"])", "    if b == \"list\":", "        return cat([\"krt.as_list(\", x, \")\"])", "    if b == \"froz\":", "        return cat([\"krt.as_froz(\", x, \")\"])", "    if b == \"dict\":", "        return cat([\"krt.as_dict(\", x, \")\"])", "    return cat([\"krt.as_model(\", x, lua_str(target), \")\"])", "", "# Присоединяет спецификацию параметризованного типа к коллекции.", "func typed_wrap(str x, str target) -> str:", "    if NOT is_typed_spec(target):", "        return x", "    str b = base_type(target)", "    if b == \"list\":", "        return cat([\"krt.typed_list(\", lua_str(target), \", \", x, \")\"])", "    if b == \"froz\":", "        return cat([\"krt.typed_froz(\", lua_str(target), \", \", x, \")\"])", "    if b == \"dict\":", "        return cat([\"krt.typed_dict(\", lua_str(target), \", \", x, \")\"])", "    return x", "", "func coerce_to(str x, str ety, str target) -> str:", "    if ety == \"str\" AND target == \"flint\":", "        return cat([\"krt.to_flint(\", x, \")\"])", "    return x", "", "func checked(str x, str ety, bool nullable, str target) -> str:", "    x = coerce_to(x, ety, target)", "    if ety == \"any\" AND NOT nullable:", "        return as_base(x, target)", "    return x", "", "func wrap_to(str x, str ety, bool nullable, str target) -> str:", "    x = coerce_to(x, ety, target)", "    if ety == \"NONE\" OR ety == \"any\" OR nullable:", "        return as_base(x, target)", "    return x", "", "func ordered_x(str x, dict e, dict other) -> str:", "    if e[t] == \"NONE\" OR e_nullable(e):", "        str ty = e[t]", "        if ty == \"NONE\":", "            ty = other[t]", "        if ty == \"str\":", "            return cat([\"krt.as_str(\", x, \")\"])", "        return cat([\"krt.as_flint(\", x, \")\"])", "    return x", "", "func emit_line(dict st, str s):", "    if NOT (st[cur_pos] is NONE):", "        dict cp = st[cur_pos]", "        if len(cp) > 0:", "            list lm = st[line_map]", "            lm.add({gen: len(st[out]) + 1, line: cp[line], col: cp[col]})", "    list o = st[out]", "    o.add(cat([spaces(st[indent] * 4), s]))", "", "func stmt_pos(dict s) -> dict:", "    str sk = s[k]", "    if sk == \"panic\":", "        return {line: s[line], col: s[col]}", "    if sk == \"decl\" OR sk == \"assign\" OR sk == \"compound\" OR sk == \"exprstmt\" OR sk == \"return\":", "        if s.contains(\"expr\"):", "            dict e = s[expr]", "            return {line: e[line], col: e[col]}", "    if sk == \"if\":", "        list brs = s[branches]", "        dict b0 = brs[0]", "        dict c0 = b0[cond]", "        return {line: c0[line], col: c0[col]}", "    if sk == \"while\":", "        dict wc = s[cond]", "        return {line: wc[line], col: wc[col]}", "    if sk == \"for\":", "        if s.contains(\"from\"):", "            dict fe = s[from]", "            return {line: fe[line], col: fe[col]}", "        dict te = s[to]", "        return {line: te[line], col: te[col]}", "    if sk == \"for_in\":", "        dict cc = s[coll]", "        return {line: cc[line], col: cc[col]}", "    return {line: s[line], col: s[col]}", "", "# Future statically has the result type; the wait is inserted at the first use.", "# Assignment to a variable is not a use: emit_future_call keeps the future in", "# the variable, and emit_await_var waits when that variable is read.", "func register_future(dict st, str lua, str ety, bool nullable, str target):", "    dict fu = st[futures]", "    fu.add(lua, TRUE)", "    dict fts = st[future_types]", "    fts.add(lua, {ety: ety, nullable: nullable, target: target})", "", "func emit_await_var(dict st, str lua) -> str:", "    dict fu = st[futures]", "    if NOT fu.contains(lua):", "        return lua", "    str x = cat([\"krt.future_await(\", lua, \")\"])", "    dict fts = st[future_types]", "    if fts.contains(lua):", "        dict fi = fts.take(lua)", "        fts.add(lua, fi)", "        x = checked(x, fi[\"ety\"], fi[\"nullable\"], fi[\"target\"])", "        if fi[\"ety\"] != \"NONE\":", "            x = typed_wrap(x, fi[\"target\"])", "    return x", "", "# Выражение -> текст Lua. Рекурсивна только сама в себя.", "func emit_expr(dict st, dict e) -> str:", "    str k = e[k]", "", "    if k == \"num\":", "        return cat([\"(\", str(e[value]), \")\"])", "    if k == \"bool\":", "        if e[value]:", "            return \"true\"", "        return \"false\"", "    if k == \"none\":", "        return \"krt.NONE\"", "    if k == \"const\":", "        return cat([\"krt.\", e[name]])", "    if k == \"var\":", "        return emit_await_var(st, e[lua])", "", "    if k == \"model_field\":", "        return cat([\"krt.model_get(self, \", lua_str(e[name]), \")\"])", "    if k == \"field\":", "        return cat([\"krt.model_get(\", emit_expr(st, e[base]), \", \", lua_str(e[name]), \")\"])", "    if k == \"model_new\":", "        list mna = e[args]", "        list mnp = [lua_str(e[mname])]", "        flint mni = 0", "        list mnpt = e[ptypes]", "        while mni < len(mna):", "            dict mnarg = mna[mni]", "            mnp.add(coerce_to(emit_expr(st, mnarg), mnarg[t], mnpt[mni]))", "            mni += 1", "        return cat([\"krt.model_new(\", mnp.join(\", \"), \")\"])", "    if k == \"model_init\":", "        list mia = e[args]", "        list mip = []", "        for mia0 in mia:", "            dict mian = mia0", "            dict miax = mian[expr]", "            mip.add(cat([\"[\", lua_str(mian[name]), \"] = \", coerce_to(emit_expr(st, miax), miax[t], mian[type])]))", "        return cat([\"krt.model_init(\", lua_str(e[mname]), \", \\{\", mip.join(\", \"), \"\\})\"])", "    if k == \"model_method\":", "        list mma2 = e[args]", "        list mmp2 = [emit_expr(st, e[base]), lua_str(e[name])]", "        list mmpt2 = e[ptypes]", "        flint mmi2 = 0", "        while mmi2 < len(mma2):", "            dict mmarg = mma2[mmi2]", "            str mmtgt = mmpt2[mmi2]", "            mmp2.add(wrap_to(emit_expr(st, mmarg), mmarg[t], e_nullable(mmarg), mmtgt))", "            mmi2 += 1", "        return cat([\"krt.model_call(\", mmp2.join(\", \"), \")\"])", "    if k == \"self_init\":", "        return \"krt.NONE\"", "", "    if k == \"func_ref\":", "        return e[lua]", "", "    if k == \"str\" OR k == \"call\":", "        list parts = e[parts]", "        list pieces = []", "        for p0 in parts:", "            dict p = p0", "            if p[kind] == \"text\":", "                pieces.add(lua_str(p[value]))", "            else:", "                dict pe = p[expr]", "                str conv = \"krt.tostr\"", "                dict range_names = st[range_floats]", "                if NOT (range_names is NONE) AND pe[k] == \"var\" AND range_names.contains(pe[lua]):", "                    conv = \"krt.tostr_range_flint\"", "                pieces.add(cat([conv, \"(\", emit_expr(st, pe), \")\"]))", "        str body = \"\\\"\\\"\"", "        if len(pieces) == 1:", "            body = pieces[0]", "        elif len(pieces) > 1:", "            body = cat([\"(\", pieces.join(\" .. \"), \")\"])", "        if k == \"str\":", "            return body", "        str f = e[fn]", "        if f == \"show\":", "            return cat([\"krt.show(\", body, \")\"])", "        if f == \"show_err\":", "            return cat([\"krt.show_err(\", body, \")\"])", "        return cat([\"krt.input(\", body, \")\"])", "", "    if k == \"builtin\":", "        str bn = e[name]", "        list ba = e[args]", "        if bn == \"args\":", "            return \"krt.args()\"", "        if bn == \"time_ms\":", "            return \"krt.time_ms()\"", "        if bn == \"is_tty\":", "            return \"krt.is_tty()\"", "        dict a0 = ba[0]", "        if bn == \"timer\":", "            dict ta1 = ba[1]", "            return cat([\"krt.timer(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \", \", emit_expr(st, ta1), \")\"])", "        if bn == \"len\":", "            return cat([\"krt.len(\", emit_expr(st, a0), \")\"])", "        if bn == \"type\":", "            return cat([\"krt.typeof(\", emit_expr(st, a0), \")\"])", "        if bn == \"str\":", "            return cat([\"krt.tostr(\", emit_expr(st, a0), \")\"])", "        if bn == \"flint\":", "            return cat([\"krt.to_flint(\", emit_expr(st, a0), \")\"])", "        if bn == \"up\":", "            return cat([\"krt.str_up(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"low\":", "            return cat([\"krt.str_low(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"title\":", "            return cat([\"krt.str_title(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"abs\":", "            return cat([\"krt.num_abs(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"round\":", "            return cat([\"krt.num_round(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"floor\":", "            return cat([\"krt.num_floor(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"ceil\":", "            return cat([\"krt.num_ceil(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"sqrt\":", "            return cat([\"krt.num_sqrt(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"factorial\":", "            return cat([\"krt.num_factorial(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"fib\":", "            return cat([\"krt.num_fib(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"rand_num\":", "            return cat([\"krt.rand_num(\", emit_expr(st, a0), \")\"])", "        if bn == \"rand_choice\":", "            return cat([\"krt.rand_choice(\", emit_expr(st, a0), \")\"])", "        if bn == \"min\" OR bn == \"max\":", "            list mvals = []", "            for mn0 in ba:", "                dict mnode = mn0", "                if base_type(mnode[t]) == \"list\":", "                    mvals.add(wrap_list(emit_expr(st, mnode), mnode[t], e_nullable(mnode)))", "                else:", "                    mvals.add(wrap_flint(emit_expr(st, mnode), mnode[t], e_nullable(mnode)))", "            return cat([\"krt.num_\", bn, \"(\", mvals.join(\", \"), \")\"])", "        if bn == \"sum\":", "            return cat([\"krt.coll_sum(\", wrap_list(emit_expr(st, a0), a0[t